-- V95 — Egypt's full administrative division (user-supplied
-- dataset, 2026-11-23): 7 regions, the 27 governorates linked
-- to their region and source id, and all 396 cities/districts
-- with proper keys, foreign keys and indexes. Governorates keep
-- their ISO-style codes as the primary key used across the
-- platform; cities reference them by that key.
CREATE TABLE IF NOT EXISTS ref_regions (
  id SMALLINT PRIMARY KEY, name_ar TEXT NOT NULL, name_en TEXT NOT NULL);
ALTER TABLE ref_governorates ADD COLUMN IF NOT EXISTS source_id SMALLINT;
ALTER TABLE ref_governorates ADD COLUMN IF NOT EXISTS region_id SMALLINT REFERENCES ref_regions(id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ref_governorates_source ON ref_governorates(source_id);
CREATE INDEX IF NOT EXISTS idx_ref_governorates_region ON ref_governorates(region_id);
CREATE TABLE IF NOT EXISTS ref_cities (
  id INT PRIMARY KEY,
  governorate_code TEXT NOT NULL REFERENCES ref_governorates(code),
  name_ar TEXT NOT NULL, name_en TEXT NOT NULL,
  UNIQUE (governorate_code, name_ar));
CREATE INDEX IF NOT EXISTS idx_ref_cities_gov ON ref_cities(governorate_code);
CREATE INDEX IF NOT EXISTS idx_ref_cities_name ON ref_cities(name_ar);
GRANT ALL ON ref_regions, ref_cities TO app_user;

